node --input-type=module -e "
import { createPushGate } from './bot.mjs';
const assert = (c, m) => { if (!c) throw new Error('FAIL: ' + m); console.log('ok -', m); };
const u = { id: 'u_8841', timeZone: 'Asia/Tokyo', quietStart: '22:00', quietEnd: '07:00', dailyCap: 3 };
let g = createPushGate();
assert(JSON.stringify(g.attempt(u, new Date('2026-10-23T03:00:00+09:00'))) === '{\"allowed\":false,\"reason\":\"quiet_hours\"}', 'quiet 03:00 Tokyo blocked');
assert(g.attempt(u, new Date('2026-10-23T07:00:00+09:00')).allowed === true, 'end minute 07:00 allowed');
assert(g.attempt(u, new Date('2026-10-23T21:59:00+09:00')).allowed === true, '21:59 allowed');
assert(g.attempt(u, new Date('2026-10-23T22:00:00+09:00')).reason === 'quiet_hours', 'start minute 22:00 blocked');
assert(g.attempt(u, new Date('2026-10-23T12:00:00+09:00')).reason === 'daily_cap_reached', 'cap 3 reached on local day');
assert(g.attempt(u, new Date('2026-10-23T23:30:00+09:00')).reason === 'quiet_hours', 'quiet beats cap');
assert(g.attempt(u, new Date('2026-10-24T08:00:00+09:00')).allowed === true, 'new local day resets cap');
// local day, not UTC: 2026-10-23T23:30 UTC is 10-24 08:30 Tokyo
const g2 = createPushGate();
const d = { id: 'u_2', timeZone: 'Asia/Tokyo', quietStart: '22:00', quietEnd: '07:00', dailyCap: 1 };
assert(g2.attempt(d, new Date('2026-10-23T15:00:00Z')).allowed === true, 'Tokyo 00:00 10-24 allowed (UTC 10-23 15:00)');
assert(g2.attempt(d, new Date('2026-10-23T16:00:00Z')).reason === 'daily_cap_reached', 'same Tokyo day capped');
// wrap window and DST in New York: 2026-03-08 02:00 -> 03:00 jump
const ny = createPushGate();
const n = { id: 'u_3', timeZone: 'America/New_York', quietStart: '22:00', quietEnd: '07:00', dailyCap: 5 };
assert(ny.attempt(n, new Date('2026-03-08T06:30:00Z')).reason === 'quiet_hours', 'NY 01:30 EST quiet');
assert(ny.attempt(n, new Date('2026-03-08T11:00:00Z')).allowed === true, 'NY 07:00 EDT allowed after DST');
// invalid inputs are held with distinct codes
assert(ny.attempt({ ...n, timeZone: 'Mars/Olympus' }, new Date()).reason === 'invalid_time_zone', 'bad zone held');
assert(ny.attempt({ ...n, quietStart: '7pm' }, new Date()).reason === 'invalid_quiet_hours', 'bad quiet held');
assert(ny.attempt({ ...n, dailyCap: -1 }, new Date()).reason === 'invalid_daily_cap', 'bad cap held');
assert(ny.attempt(n, new Date('nope')).reason === 'invalid_time', 'bad now held');
// independent gates and per-user counts; cap 0 blocks all
assert(createPushGate().attempt(n, new Date('2026-03-08T16:00:00Z')).allowed === true, 'fresh gate has own history');
assert(createPushGate().attempt({ ...n, id: 'u_z', dailyCap: 0 }, new Date('2026-03-08T16:00:00Z')).reason === 'daily_cap_reached', 'cap 0 blocks');
// quiet window with equal start and end is empty
assert(createPushGate().attempt({ ...n, quietStart: '08:00', quietEnd: '08:00' }, new Date('2026-03-08T13:00:00Z')).allowed === true, 'equal start/end = no quiet');
console.log('all checks passed');
"

